import{_ as t,a,b as i,c as s,d as r,e as o,f as n}from"./chunks/specialized-sites.KzKMyxDZ.js";import{_ as d,o as l,c,a3 as p}from"./chunks/framework.BPaanrMb.js";const k=JSON.parse('{"title":"Short-Distance Autonomous Transport Applications","description":"Decision guide for short-distance autonomous transport in manufacturing, healthcare, retail, logistics parks, campuses and specialized sites.","frontmatter":{"title":"Short-Distance Autonomous Transport Applications","description":"Decision guide for short-distance autonomous transport in manufacturing, healthcare, retail, logistics parks, campuses and specialized sites.","status":"design guidance","content_type":"application","keywords":["short-distance transport","manufacturing","medical logistics","retail replenishment","logistics park","campus logistics","port","airport"],"scope":"Repetitive short-distance transport inside enterprises, hospitals, retail networks, logistics parks and large institutions","decision_summary":"Prioritize frequent, fixed-route transport with standardized handoffs and a clear operating owner. Healthcare and specialized sites also require regulatory and safety approval.","best_for":["high-frequency repetitive transport","fixed or semi-fixed routes","trips under 5 km","standardized loading and handoff","a clear paying customer"],"not_for":["infrequent transport","no stable operating owner","highly uncertain routes and handoffs","unresolved regulation or insurance","autonomous driving as a demonstration only"],"next_action":"Send the site, vehicle, route, shift, handoff process and compliance requirements for an application-fit assessment.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20short-distance%20transport%20assessment"},"headers":[],"relativePath":"en/solutions/applications.md","filePath":"en/solutions/applications.md","lastUpdated":1794551845000}'),u={name:"en/solutions/applications.md"};function h(m,e,g,f,y,v){return l(),c("div",null,[...e[0]||(e[0]=[p('<h1 id="short-distance-autonomous-transport-applications" tabindex="-1">Short-Distance Autonomous Transport Applications <a class="header-anchor" href="#short-distance-autonomous-transport-applications" aria-label="Permalink to &quot;Short-Distance Autonomous Transport Applications&quot;">​</a></h1><blockquote><p>This page is an application-selection and business-decision guide, not a performance, regulatory or safety certification. Every project must validate the site, vehicle, tasks, regulations and unit economics.</p></blockquote><figure class="application-visual application-visual--lead"><img src="'+t+'" alt="WheelOS short-distance autonomous transport applications in manufacturing, healthcare, retail and large campuses" width="1600" height="1066" loading="eager"><figcaption>WheelOS focuses on fixed short-distance transport across manufacturing, healthcare, retail, logistics and large campuses.</figcaption></figure><div id="decision-summary"></div><h2 id="decision-summary" tabindex="-1">Decision summary <a class="header-anchor" href="#decision-summary" aria-label="Permalink to &quot;Decision summary&quot;">​</a></h2><p>WheelOS focuses on <strong>frequent, repetitive, short-distance material transport</strong> inside an enterprise or institution. The best first project is not “autonomous driving everywhere.” It is a concrete transport task that meets all of these conditions:</p><ul><li>A typical one-way trip is under about 5 km, mainly inside a campus, between adjacent sites or around a warehouse.</li><li>The task repeats every day with stable shifts and a clear operating owner.</li><li>Origins, destinations, loading areas and handoffs are relatively fixed.</li><li>Route, vehicle, cargo, regulatory and insurance boundaries can be assessed.</li></ul><p><strong>5 km is the current focus for exploration, not an absolute technical limit.</strong></p><p><a href="/en/solutions/fit-assessment">Check your transport task with the five-gate assessment →</a></p><div id="scenario-priority"></div><h2 id="scenario-priority" tabindex="-1">Scenario priority <a class="header-anchor" href="#scenario-priority" aria-label="Permalink to &quot;Scenario priority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Customer task</th><th>Main value lever</th><th>Priority</th><th>Validate first</th></tr></thead><tbody><tr><td>Manufacturing</td><td>Material movement among warehouses, workshops, lines and finished-goods stores</td><td>Multi-shift labor, staffing and vehicle dispatch</td><td>Explore first</td><td>Outdoor cross-building routes, chassis, loading cadence, mixed traffic</td></tr><tr><td>Medical logistics</td><td>Specimens and supplies among hospitals, laboratories and hospital groups</td><td>Fixed time windows, repeated trips and handoff records</td><td>High value, regulated</td><td>Transport qualification, temperature, biosafety, packaging, chain of custody</td></tr><tr><td>Retail replenishment</td><td>Small-batch replenishment from a regional warehouse to nearby stores</td><td>Frequent delivery, store inventory and dispatch organization</td><td>Pilot by delivery cluster</td><td>Store density, loading windows, cold chain, urban mixed traffic</td></tr><tr><td>Logistics campus</td><td>Movement among warehouses, docks and staging areas</td><td>Central dispatch, fewer short-haul staff and less empty running</td><td>Strong fit</td><td>Site map, traffic rules, dock cadence, system interfaces</td></tr><tr><td>Campus and large venue</td><td>Food, linen, consumables and other facility tasks</td><td>Combining tasks and improving vehicle utilization</td><td>Aggregate tasks first</td><td>Task frequency, multi-building handoffs, operating owner, mixed traffic</td></tr><tr><td>Port, airport and specialized sites</td><td>Fixed shuttling and horizontal transport</td><td>Large demand, fixed area and specialized operations</td><td>Later projects</td><td>Specialized vehicles, site systems, safety access, long-term operations</td></tr></tbody></table><div id="manufacturing"></div><h2 id="_1-manufacturing-material-transport" tabindex="-1">1. Manufacturing material transport <a class="header-anchor" href="#_1-manufacturing-material-transport" aria-label="Permalink to &quot;1. Manufacturing material transport&quot;">​</a></h2><figure class="application-visual"><img src="'+a+'" alt="Material transport between factory warehouses, workshops and production lines" width="1280" height="800" loading="lazy"><figcaption>Material movement among factory warehouses, workshops, production lines and finished-goods stores.</figcaption></figure><p><strong>Problem:</strong> Raw materials, parts and work-in-progress move continuously among warehouses, workshops and production lines. Some routes are short but run many times per day.</p><p><strong>Typical customers:</strong> Automotive-parts, electronics, appliance, machining and food manufacturers; industrial parks.</p><p><strong>Value metrics:</strong> Trips per shift, driver and material-handler effort, vehicle waiting, on-time performance, cost per trip, night-shift and cross-building capability.</p><p><strong>Commercial models:</strong> System purchase and vehicle adaptation; fixed-route monthly service; system and operations service by vehicle or shift; customer or logistics contractor vehicle ownership.</p><p><strong>Entry conditions:</strong> Start with outdoor cross-building or warehouse-to-workshop routes. The production plan should make task cadence and loading demand visible instead of relying on ad-hoc dispatch.</p><div id="medical-logistics"></div><h2 id="_2-medical-and-pharmaceutical-transport" tabindex="-1">2. Medical and pharmaceutical transport <a class="header-anchor" href="#_2-medical-and-pharmaceutical-transport" aria-label="Permalink to &quot;2. Medical and pharmaceutical transport&quot;">​</a></h2><figure class="application-visual"><img src="'+i+'" alt="Medical supply transport between hospitals and laboratories" width="1280" height="720" loading="lazy"><figcaption>Specimen and medical-supply transport among hospital campuses and laboratories; professional compliance requirements still apply.</figcaption></figure><p><strong>Problem:</strong> Hospitals, laboratories and hospital groups need frequent, small-batch, time-defined movement of specimens and supplies.</p><p><strong>Typical customers:</strong> Hospital groups, integrated care networks, third-party medical laboratories, pharmaceutical distributors and community health centers.</p><p><strong>Value metrics:</strong> Time-window compliance, trips per day, complete handoffs, exception response, manual courier effort.</p><p><strong>Commercial models:</strong> Fixed-route transport contract; per-shift or service-volume settlement; technology supplied to a qualified medical-logistics operator; multi-site hospital service.</p><p><strong>Entry conditions:</strong> A qualified customer or logistics partner must own transport licensing, temperature control, biosafety, packaging, chain of custody and incident handling. Autonomous driving does not replace those requirements.</p><div id="retail-replenishment"></div><h2 id="_3-retail-and-chain-store-replenishment" tabindex="-1">3. Retail and chain-store replenishment <a class="header-anchor" href="#_3-retail-and-chain-store-replenishment" aria-label="Permalink to &quot;3. Retail and chain-store replenishment&quot;">​</a></h2><figure class="application-visual"><img src="'+s+'" alt="Regional warehouse replenishing nearby chain stores" width="1280" height="720" loading="lazy"><figcaption>Small-batch replenishment from a regional warehouse or distribution center to nearby stores.</figcaption></figure><p><strong>Problem:</strong> A regional warehouse or distribution center replenishes nearby stores frequently. Small batches reduce store inventory but increase delivery organization cost.</p><p><strong>Typical customers:</strong> Convenience and fresh-food chains, supermarkets, restaurant chains, central kitchens and supply-chain companies.</p><p><strong>Value metrics:</strong> Delivery timeliness, stock-out rate, cost per delivery, vehicle fill, vehicle turns and store waiting time.</p><p><strong>Commercial models:</strong> Fixed store-route service; per-store, per-shift or per-task fee; vehicle leasing or capacity by usage time; centralized capacity purchase by the chain.</p><p><strong>Entry conditions:</strong> Prioritize stores within about 5 km of a warehouse that can form a route cluster. Confirm loading windows, cold-chain requirements, store handoffs and the urban operating boundary.</p><div id="logistics-campus"></div><h2 id="_4-warehouse-and-logistics-campus-transport" tabindex="-1">4. Warehouse and logistics-campus transport <a class="header-anchor" href="#_4-warehouse-and-logistics-campus-transport" aria-label="Permalink to &quot;4. Warehouse and logistics-campus transport&quot;">​</a></h2><figure class="application-visual"><img src="'+r+'" alt="Short-distance transport among warehouses, docks and staging areas in a logistics campus" width="1280" height="853" loading="lazy"><figcaption>Short-haul movement among warehouses, loading docks and staging areas.</figcaption></figure><p><strong>Problem:</strong> Multiple warehouses, docks, staging areas and tenant operations create continuous short-haul transfer demand.</p><p><strong>Typical customers:</strong> Warehouse operators, logistics parks, wholesale markets, supply-chain companies, bonded-zone businesses and regional distribution centers.</p><p><strong>Value metrics:</strong> Transfer trips, dock waiting, empty running, vehicles under central dispatch and task completion.</p><p><strong>Commercial models:</strong> Fixed-route and periodic service; per-day task or throughput; campus-wide purchase; shared transport service built by the campus operator.</p><p><strong>Entry conditions:</strong> Stable maps, traffic rules and operational interfaces are important. A concentrated tenant base with dispatchable tasks supports a stronger operating loop.</p><div id="campus-logistics"></div><h2 id="_5-campus-hotel-and-large-venue-logistics" tabindex="-1">5. Campus, hotel and large-venue logistics <a class="header-anchor" href="#_5-campus-hotel-and-large-venue-logistics" aria-label="Permalink to &quot;5. Campus, hotel and large-venue logistics&quot;">​</a></h2><figure class="application-visual"><img src="'+o+'" alt="Facility logistics among buildings in a campus, hotel or large venue" width="1280" height="720" loading="lazy"><figcaption>Logistics among kitchens, laundry, warehouses and different buildings.</figcaption></figure><p><strong>Problem:</strong> Food, linen, supplies and equipment move among buildings, kitchens, warehouses and service areas, but any single task may be infrequent.</p><p><strong>Typical customers:</strong> Universities, hospital campuses, hotel groups, resorts, scenic areas, property managers and industrial-park operators.</p><p><strong>Value metrics:</strong> Combined task density, vehicle utilization, multi-building handoffs and manual handling effort.</p><p><strong>Commercial models:</strong> Central purchase by the property or campus operator; monthly transport service; combined multi-task service; route and time-window pricing.</p><p><strong>Entry conditions:</strong> Combine food, linen and consumable tasks first and prove vehicle utilization. Avoid deploying a dedicated vehicle for one low-frequency task.</p><div id="specialized-sites"></div><h2 id="_6-ports-airports-and-specialized-operating-areas" tabindex="-1">6. Ports, airports and specialized operating areas <a class="header-anchor" href="#_6-ports-airports-and-specialized-operating-areas" aria-label="Permalink to &quot;6. Ports, airports and specialized operating areas&quot;">​</a></h2><figure class="application-visual"><img src="'+n+'" alt="Fixed-route cargo transport inside a port, airport or specialized operating area" width="1280" height="720" loading="lazy"><figcaption>Fixed-route transport inside ports, airports and specialized operating areas.</figcaption></figure><p><strong>Problem:</strong> Ports, airports, rail yards and energy sites need fixed cargo shuttling and horizontal transport inside a defined operating area.</p><p><strong>Typical customers:</strong> Port and airport operators, rail freight centers, energy companies and specialized-site operators.</p><p><strong>Value metrics:</strong> Fixed-segment throughput, utilization, dispatch integration, downtime, safety events and all-weather operation.</p><p><strong>Commercial models:</strong> Project-based system integration, specialized-vehicle adaptation, autonomous-system licensing and long-term operations.</p><p><strong>Entry conditions:</strong> These projects often involve specialized vehicles, site systems, safety access and complex dispatch. They can become major accounts, but should not be the only early market.</p><div id="commercial-models"></div><h2 id="commercial-models" tabindex="-1">Commercial models <a class="header-anchor" href="#commercial-models" aria-label="Permalink to &quot;Commercial models&quot;">​</a></h2><p>The model must match the vehicle owner, operating entity, carrier responsibility and customer budget. The following structures are options for discussion; final responsibilities belong in the contract.</p><h3 id="customer-and-wheelos-responsibilities" tabindex="-1">Customer and WheelOS responsibilities <a class="header-anchor" href="#customer-and-wheelos-responsibilities" aria-label="Permalink to &quot;Customer and WheelOS responsibilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Party</th><th>Typically responsible for</th><th>Not assumed by default</th></tr></thead><tbody><tr><td>Customer</td><td>Site, transport tasks, vehicles or purchase plan, loading and handoff, operations team, required permits and insurance</td><td>Business compliance, carrier responsibility and day-to-day site operations</td></tr><tr><td>WheelOS</td><td>Kit configuration, software/interface documentation, integration support, calibration and validation guidance, optional-service quotation</td><td>Logistics carriage or sector licensing not agreed in the contract</td></tr><tr><td>Joint confirmation</td><td>ODD, routes, acceptance metrics, data and logs, safety boundary, project plan and responsibility split</td><td>Neither party may turn design guidance into a verified safety claim</td></tr></tbody></table><h3 id="commercial-options" tabindex="-1">Commercial options <a class="header-anchor" href="#commercial-options" aria-label="Permalink to &quot;Commercial options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>What the customer buys</th><th>Best customer structure</th><th>Key boundary</th></tr></thead><tbody><tr><td>Autonomous-system purchase</td><td>Vehicle/system adaptation, deployment and technical support</td><td>Customer owns vehicles and operations</td><td>Define hardware, software, adaptation and support scope</td></tr><tr><td>Fixed-route transport service</td><td>Service by route, shift or monthly volume</td><td>Customer or partner operates the fleet</td><td>Separate WheelOS technology responsibility from carrier responsibility</td></tr><tr><td>Vehicle leasing and capacity service</td><td>Capacity by lease period or usage</td><td>Customer wants lower upfront investment</td><td>Vehicle ownership, insurance and incident responsibility must be explicit</td></tr><tr><td>Software and operations subscription</td><td>Autonomous system, fleet management and ongoing support</td><td>Operator with multiple vehicles and routes</td><td>Confirm functions, SLA and data responsibility</td></tr></tbody></table><div id="fit-checklist"></div><h2 id="fit-checklist" tabindex="-1">Fit checklist <a class="header-anchor" href="#fit-checklist" aria-label="Permalink to &quot;Fit checklist&quot;">​</a></h2><p>Before quoting, answer:</p><ol><li>How many trips occur each day, and are multiple shifts or night operations required?</li><li>How many drivers, material handlers and vehicles are used today?</li><li>Are routes fixed, and are there mixed-traffic areas, temporary obstacles or complex junctions?</li><li>Are goods and loading/handoff processes standardized?</li><li>Who owns the budget and purchase decision, and is there a long-term operating plan?</li><li>How many productive tasks can one vehicle complete per day?</li><li>Is operation legally permitted, and how are insurance and incident responsibility handled?</li></ol><p>Do not move directly to deployment when:</p><ul><li>Task frequency is too low to produce stable utilization.</li><li>No operating owner, budget or long-term plan exists.</li><li>Origins, destinations, loading or handoffs are highly uncertain.</li><li>Regulation, insurance or site safety responsibility remains unresolved.</li><li>The customer asks only for a “driverless demonstration” without a business metric.</li></ul><div id="what-wheelos-provides"></div><h2 id="what-wheelos-provides" tabindex="-1">What WheelOS provides <a class="header-anchor" href="#what-wheelos-provides" aria-label="Permalink to &quot;What WheelOS provides&quot;">​</a></h2><div class="solution-grid"><div class="solution-card"><span class="solution-card__index">01 / KIT</span><h3>Integrated Autonomous Driving Kit</h3><p>Pre-integrated compute, sensors, GNSS/INS, software and developer tools for low-speed campus project development and integration.</p></div><div class="solution-card"><span class="solution-card__index">02 / ADAPT</span><h3>Vehicle and site adaptation</h3><p>Project configuration and integration services around chassis CAN, routes, loading, calibration and validation.</p></div><div class="solution-card"><span class="solution-card__index">03 / OPERATE</span><h3>Operations planning</h3><p>Vehicle onboarding, fleet management and remote monitoring are project-planning topics; functions, SLA and delivery conditions require confirmation.</p></div></div><p>WheelOS does not operate parcel collection, sorting, last-mile delivery or parcel stations, and does not replace the compliance responsibilities of healthcare, port or airport operators.</p><div id="next-steps"></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Share the site, vehicle, routes, shifts, cargo and handoff process.</li><li>Screen task frequency, operating owner, regulation and unit economics together.</li><li>Review chassis, sensor placement, site map, safety and acceptance metrics.</li><li>Run a minimum integration and validation project in a controlled environment.</li></ol><p><a href="/en/solutions/delivery-process">See the five-milestone customer journey from requirements to pilot deployment →</a></p><div class="solution-cta"><div><h2>Assess whether your transport task fits autonomous driving</h2><p>Send the application, vehicle and operating data. We will screen fit first, then discuss the kit, services and commercial structure.</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20short-distance%20transport%20assessment">Request an assessment</a><a href="/en/solutions/fit-assessment">Start the five-gate check</a><a href="/en/solutions/delivery-process">View the delivery process</a><a href="/en/solutions/integrated-autonomous-driving-kit">View the integrated kit</a></div></div>',82)])])}const q=d(u,[["render",h]]);export{k as __pageData,q as default};
